'use strict';
const app=document.getElementById('app');
let learned=new Set();try{const saved=JSON.parse(localStorage.getItem('word-cottage-learned')||'[]');if(Array.isArray(saved))learned=new Set(saved.filter(id=>words.some(w=>w.id===id)));}catch{}
let session=null, reversed=false,screen='home';
function save(){try{localStorage.setItem('word-cottage-learned',JSON.stringify([...learned]));}catch{toast('Не вдалося зберегти прогрес у браузері.');}updateTotal();}
function updateTotal(){document.getElementById('total').textContent=learned.size;}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.className='toast-show';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',4000);}
function count(cat){return words.filter(w=>w.category===cat&&learned.has(w.id)).length;}
function tile(c){return `<div class="tile" style="background-position:${c.tile}" aria-hidden="true"></div>`;}
function home(){screen='home';session=null;app.innerHTML=`<div class="intro"><div><div class="eyebrow">Твій маленький словник</div><h1>Час для <em>нових слів.</em></h1><p class="sub">Обери розділ і почни з однієї картки.</p></div><p class="note">Чашка чаю.<br>Кілька слів.<br>Ще один маленький крок.</p></div><div class="home-layout"><section><div class="section-label"><h2>На що сьогодні настрій?</h2><span>4 розділи · 400 карток</span></div><div class="category-grid">${categories.map((c,i)=>`<button class="category ${c.color}" data-category="${c.id}"><div class="cat-top">${tile(c)}<span class="cat-number">0${i+1}</span></div><h3>${c.name}</h3><div class="en">${c.en} · 100 слів</div><p>${c.note}</p><div class="progress-row"><div class="track"><div class="fill" style="width:${count(c.id)}%"></div></div><span>${count(c.id)} / 100</span></div></button>`).join('')}</div><div class="mix"><span class="mix-symbol" aria-hidden="true">✳</span><div><h3>Змішано</h3><p>Збери слова з різних розділів.</p></div><button class="btn" id="mixed">Перемішати</button></div><p class="bottom-note">Торкнись картки, щоб побачити переклад. Повторюй, доки слово не стане знайомим.</p></section><aside class="side-art" aria-label="Затишна клаптикова ілюстрація з вашого фото"><div class="art-label">Little words,<br>little wonders.<small>ОДНЕ СЛОВО ЗА РАЗ</small></div></aside></div>`;
app.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>chooseAmount([b.dataset.category]));document.getElementById('mixed').onclick=picker;updateTotal();}
function amountControls(){return `<fieldset class="word-count-picker"><legend>Скільки слів цього разу?</legend><div class="word-stepper"><button type="button" class="step-btn" id="count-minus" aria-label="Зменшити кількість слів">−</button><output id="word-count" aria-live="polite" aria-label="Кількість слів">10</output><button type="button" class="step-btn" id="count-plus" aria-label="Збільшити кількість слів">+</button></div><div class="count-presets" aria-label="Швидкий вибір кількості">${[5,10,20].map(n=>`<button type="button" class="btn secondary count-preset" data-count="${n}" aria-pressed="${n===10}">${n} слів</button>`).join('')}</div><p class="count-available" id="count-available"></p></fieldset>`;}
function bindAmount(maximum,startButton){
  let maximumWords=maximum,amount=Math.min(10,maximum);
  const minus=document.getElementById('count-minus'),plus=document.getElementById('count-plus');
  const presets=[...app.querySelectorAll('[data-count]')];
  function update(){
    document.getElementById('word-count').textContent=amount;
    document.getElementById('count-available').textContent=maximumWords?`Доступно слів: ${maximumWords}`:'Обери хоча б один розділ.';
    minus.disabled=amount<=1;plus.disabled=amount>=maximumWords;
    presets.forEach(button=>{button.disabled=Number(button.dataset.count)>maximumWords;button.setAttribute('aria-pressed',String(Number(button.dataset.count)===amount));});
    startButton.disabled=maximumWords===0;
    startButton.textContent=maximumWords?`Почати · ${amount} ${wordLabel(amount)}`:'Почати';
  }
  minus.onclick=()=>{amount=Math.max(1,amount-1);update();};
  plus.onclick=()=>{amount=Math.min(maximumWords,amount+1);update();};
  presets.forEach(button=>button.onclick=()=>{amount=Number(button.dataset.count);update();});
  update();
  return {value:()=>amount,setMaximum(value){maximumWords=value;amount=value?Math.min(Math.max(1,amount||10),value):0;update();}};
}
function wordLabel(number){return number%10===1&&number%100!==11?'слово':number%10>=2&&number%10<=4&&(number%100<12||number%100>14)?'слова':'слів';}
function chooseAmount(ids,mixed=false){
  screen='amount';session=null;
  const category=categories.find(c=>c.id===ids[0]);
  app.innerHTML=`<div class="study-top"><button class="back" id="back">‹ Усі розділи</button></div><section class="mix-picker amount-picker"><div class="eyebrow">${mixed?'Змішано':category.en}</div><h1>${mixed?'Слова з різних розділів':category.name}</h1>${amountControls()}<button class="btn" id="start-session">Почати</button></section>`;
  document.getElementById('back').onclick=home;
  const button=document.getElementById('start-session');
  const amount=bindAmount(words.filter(w=>ids.includes(w.category)).length,button);
  button.onclick=()=>start(ids,mixed,false,amount.value());
}
function picker(){
  screen='picker';session=null;
  app.innerHTML=`<div class="study-top"><button class="back" id="back">‹ Усі розділи</button></div><section class="mix-picker"><div class="eyebrow">Трохи всього</div><h1>Змішай свій словник</h1><p class="sub">Обери розділи — картки з’являтимуться у випадковому порядку.</p><div class="pick-options">${categories.map(c=>`<label><input type="checkbox" value="${c.id}" checked><span>${c.name}</span><small>100 слів</small></label>`).join('')}</div>${amountControls()}<button class="btn" id="start-mix">Почати</button></section>`;
  document.getElementById('back').onclick=home;
  const selected=()=>[...app.querySelectorAll('.pick-options input:checked')].map(x=>x.value);
  const button=document.getElementById('start-mix');
  const amount=bindAmount(words.length,button);
  app.querySelectorAll('.pick-options input').forEach(input=>input.onchange=()=>amount.setMaximum(words.filter(w=>selected().includes(w.category)).length));
  button.onclick=()=>{if(selected().length)start(selected(),true,false,amount.value());};
}
function shuffle(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function start(ids,mixed=false,onlyNew=false,limit=null){if(!Array.isArray(ids)||!ids.length||ids.some(id=>!categories.some(c=>c.id===id)))throw Error('Невідомий розділ');if(limit!==null&&(!Number.isInteger(limit)||limit<1))throw Error('Некоректна кількість слів');let list=words.filter(w=>ids.includes(w.category)&&(!onlyNew||!learned.has(w.id)));if(mixed)list=shuffle(list);if(limit!==null)list=list.slice(0,limit);session={ids,mixed,onlyNew,limit,queue:list,index:0,flipped:false,correct:0,review:[],initial:list.length};screen='study';renderStudy();}
function renderStudy(){const s=session;const c=categories.find(c=>c.id===s.ids[0]);app.innerHTML=`<div class="study-top"><button class="back" id="back">‹ Усі розділи</button><span class="en">${s.queue.length} ${wordLabel(s.queue.length)} у цій сесії</span></div><div class="study-layout"><aside class="study-aside">${tile(c)}<div class="eyebrow">${s.mixed?'Mix & learn':c.en}</div><h1>${s.mixed?'Змішано':c.name}</h1><p class="sub">Не поспішай. Дай слову час.</p><div class="settings"><label for="direction">Напрямок</label><select id="direction"><option value="en">English → Українська</option><option value="uk">Українська → English</option></select><label class="check"><input id="only-new" type="checkbox" ${s.onlyNew?'checked':''}> Лише невивчені</label></div></aside><section class="study-main" id="study-content"></section></div>`;document.getElementById('back').onclick=home;const d=document.getElementById('direction');d.value=reversed?'uk':'en';d.onchange=()=>{reversed=d.value==='uk';s.flipped=false;renderCard();};document.getElementById('only-new').onchange=e=>start(s.ids,s.mixed,e.target.checked,s.limit);renderCard();}
function renderCard(){const s=session,box=document.getElementById('study-content');if(s.index>=s.queue.length){box.innerHTML=`<div class="done"><div class="eyebrow">${s.initial?'Гарна робота':'Усе вже знайоме'}</div><h2>${s.initial?'Ще один маленький крок!':'Ці слова вже вивчено'}</h2><p>${s.initial?`За цю сесію: ${s.correct} знайомих слів.<br>Ще повторити: ${s.review.length}.`:'Можеш повторити весь розділ або обрати інший.'}</p>${s.review.length?'<button class="btn" id="review">Повторити складні</button>':''}<button class="btn secondary" id="restart">Почати знову</button><button class="btn secondary" id="done-home">До розділів</button></div>`;if(s.review.length)document.getElementById('review').onclick=()=>{s.queue=shuffle(s.review);s.initial=s.queue.length;s.review=[];s.index=0;s.correct=0;s.flipped=false;renderCard();};document.getElementById('restart').onclick=()=>start(s.ids,s.mixed,false,s.limit);document.getElementById('done-home').onclick=home;return;}
const w=s.queue[s.index],c=categories.find(c=>c.id===w.category),isUk=reversed!==s.flipped;
box.innerHTML=`<div class="session-status"><span>${c.name}</span><span>${s.index+1} / ${s.queue.length}</span></div><div class="flashcard" id="flashcard" tabindex="0" role="button" aria-label="${s.flipped?'Показати слово':'Показати переклад'}"><div class="card-tag">${isUk?'Українська':'English'}</div><div class="word ${isUk?'uk':''}" lang="${isUk?'uk':'en'}">${isUk?w.uk:w.en}</div><div class="card-hint">${s.flipped?'Як добре пам’ятаєш це слово?':'Торкнись, щоб побачити переклад'}</div></div><div style="text-align:center"><button class="speak" id="speak" aria-label="Послухати англійську вимову">♫ Послухати вимову</button></div><div class="actions">${s.flipped?'<button class="btn repeat" id="repeat">Ще повторю</button><button class="btn" id="known">Знаю ✓</button>':'<button class="btn" id="reveal">Показати переклад</button>'}</div><div class="study-progress"><div class="track"><div class="fill" style="width:${s.index/s.queue.length*100}%"></div></div></div><p class="key-hint">Пробіл — перевернути · 1 — ще повторю · 2 — знаю</p>`;
const flip=()=>{s.flipped=!s.flipped;renderCard();};document.getElementById('flashcard').onclick=flip;document.getElementById('flashcard').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();flip();}};document.getElementById('speak').onclick=()=>speak(w.en);if(s.flipped){document.getElementById('repeat').onclick=()=>rate(false);document.getElementById('known').onclick=()=>rate(true);}else document.getElementById('reveal').onclick=flip;}
function rate(known){if(!session||!session.flipped||session.index>=session.queue.length)return;const w=session.queue[session.index];if(known){learned.add(w.id);session.correct++;}else{learned.delete(w.id);session.review.push(w);}save();session.index++;session.flipped=false;renderCard();}
function speak(word){if(!('speechSynthesis'in window)){toast('Цей браузер не підтримує озвучення.');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(word);u.lang='en-GB';u.rate=.8;const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang==='en-GB')||voices.find(v=>v.lang.startsWith('en'))||null;u.onerror=e=>{if(e.error!=='interrupted'&&e.error!=='canceled')toast('Озвучення недоступне. Перевір налаштування голосів пристрою.');};speechSynthesis.speak(u);}
document.querySelector('.brand').onclick=e=>{e.preventDefault();home();};document.addEventListener('keydown',e=>{if(screen!=='study'||!session||session.index>=session.queue.length||['INPUT','SELECT','BUTTON','A'].includes(document.activeElement.tagName))return;if(e.code==='Space'){e.preventDefault();session.flipped=!session.flipped;renderCard();}if(e.key==='1')rate(false);if(e.key==='2')rate(true);});
home();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_word_practice',description:'Почати вивчення слів із вибраних розділів. Не змінює вивчені слова.',inputSchema:{type:'object',properties:{categories:{type:'array',items:{type:'string',enum:categories.map(c=>c.id)},minItems:1},mixed:{type:'boolean'}},required:['categories'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||(input.mixed!==undefined&&typeof input.mixed!=='boolean'))throw Error('Некоректні параметри');start(input.categories,Boolean(input.mixed));return{screen:'study',cards:session.queue.length,categories:session.ids};}})).catch(()=>{});}catch{}}
